import json,os,pathlib,subprocess
keys={'DISPLAY','WAYLAND_DISPLAY','XAUTHORITY','XDG_SESSION_TYPE','QT_QPA_PLATFORM'}
procs=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  comm=(p/'comm').read_text().strip()
  if comm in {'FreeCAD','gnome-shell','Xorg','Xwayland'}:
   env={}
   try:
    for pair in (p/'environ').read_bytes().split(b'\0'):
     k,_,v=pair.partition(b'=')
     if k.decode(errors='replace') in keys:env[k.decode()]=v.decode(errors='replace')
   except PermissionError:pass
   procs.append({'pid':p.name,'comm':comm,'display':env})
 except (FileNotFoundError,PermissionError,ProcessLookupError):pass
files={}
for name in ('/snap/freecad/current/meta/snap.yaml','/home/user/.config/autostart/freecad.desktop'):
 p=pathlib.Path(name)
 if p.exists():files[name]=p.read_text()[:16000]
r=subprocess.run(['wmctrl','-lpG'],capture_output=True,text=True,timeout=15)
print(json.dumps({'processes':procs,'windows':r.stdout,'files':files}))

